import { GraftConfig } from "./config.js";
import { GraftUtils } from "./utils.js";
import { OwnerDto } from "./OwnerDto.js";

export class Customers {
  #instance = null;
  #args = [];

  static get type() {
    GraftConfig.init();
    return GraftConfig.rtmCtx.getType(
      "org.springframework.samples.petclinic.customers.model.Customers",
    );
  }

  get instance() {
    return this.#instance;
  }

  /**
   * @param {number} petId
   * @returns {Promise<OwnerDto>}
   */
  static async getOwnerForPet(petId) {
    try {
      const returnObjectIC = await Customers.type
        .invokeStaticMethod("getOwnerForPet", petId)
        .execute();

      await GraftUtils.RegisterType(OwnerDto, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }

  /**
   * @param {number} id
   * @returns {Promise<OwnerDto>}
   */
  static async getOwner(id) {
    try {
      const returnObjectIC = await Customers.type
        .invokeStaticMethod("getOwner", id)
        .execute();

      await GraftUtils.RegisterType(OwnerDto, returnObjectIC, false);
      return GraftUtils.ConvertResult(returnObjectIC);
    } catch (ex) {
      throw GraftUtils.ExceptionWrapper(ex);
    }
  }
}
